contract FANG is ERC20Burnable, Operator {
    using SafeMath8 for uint8;
    using SafeMath for uint256;

    /**
     * @notice Constructs the FANG ERC-20 contract.
     */
    constructor() ERC20("FANG", "FANG") {
        _mint(msg.sender, 252_000 ether);
    }

    /**
     * @notice Operator mints FANG to a recipient
     * @param recipient_ The address of recipient
     * @param amount_ The amount of FANG to mint to
     * @return whether the process has been done
     */
    function mint(address recipient_, uint256 amount_) public onlyOperator returns (bool) {
        uint256 balanceBefore = balanceOf(recipient_);
        _mint(recipient_, amount_);
        uint256 balanceAfter = balanceOf(recipient_);

        return balanceAfter > balanceBefore;
    }

    function burn(uint256 amount) public override {
        super.burn(amount);
    }

    function burnFrom(address account, uint256 amount) public override onlyOperator {
        super.burnFrom(account, amount);
    }

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public override returns (bool) {
        _transfer(sender, recipient, amount);
        _approve(sender, _msgSender(), allowance(sender, _msgSender()).sub(amount, "ERC20: transfer amount exceeds allowance"));
        return true;
    }

    function governanceRecoverUnsupported(
        IERC20 _token,
        uint256 _amount,
        address _to
    ) external onlyOperator {
        _token.transfer(_to, _amount);
    }
}"
